const body = $input.item.json.body || $input.item.json;

const sessionId = body.sessionId || 'unknown';
const model = body.model || 'claude-haiku-4-5-20251001';
const inputTokens = body.usage?.input || body.inputTokens || 0;
const outputTokens = body.usage?.output || body.outputTokens || 0;
const message = body.message || '';
const response = body.response || '';
const channel = body.channel || 'discord';
const timestamp = new Date().toISOString();

return {
  json: {
    tracePayload: {
      name: 'openclaw-discord-message',
      sessionId: sessionId,
      input: { message, channel },
      output: { response },
      metadata: {
        model,
        channel,
        source: 'kisnlab-openclaw'
      },
      usage: {
        input: inputTokens,
        output: outputTokens,
        unit: 'TOKENS'
      }
    },
    generationPayload: {
      name: 'claude-response',
      traceId: null,
      model: model,
      modelParameters: {},
      input: [{ role: 'user', content: message }],
      output: { role: 'assistant', content: response },
      usage: {
        input: inputTokens,
        output: outputTokens,
        unit: 'TOKENS'
      },
      startTime: timestamp,
      endTime: timestamp
    }
  }
};
